<?= $this->section('main-content') ?>
<?php
$filters = $filters ?? ['event_type' => '', 'actor' => '', 'from' => '', 'to' => '']; $summary = $summary ?? [];
$formatEvent = static fn (string $event): string => ucwords(str_replace('_', ' ', $event ?: 'Activity'));
$category = static function (string $event): string { return str_starts_with($event, 'follow_up_') ? 'Follow-up' : (str_starts_with($event, 'converted_') ? 'Conversion' : 'Lead'); };
$icon = static function (string $event): string { return str_starts_with($event, 'follow_up_') ? 'bi-calendar2-check' : (str_starts_with($event, 'converted_') ? 'bi-arrow-left-right' : ($event === 'updated' ? 'bi-pencil-square' : 'bi-person-plus')); };
$statusClass = static fn (string $value): string => 'crm-status-badge crm-status-' . preg_replace('/[^a-z0-9_-]/', '', strtolower($value));
$safeKeys = ['full_name','mobile_number','email','gender','date_of_birth','service_name','priority','next_follow_up_date','next_follow_up_time','remarks','follow_up_date','follow_up_time','follow_up_status'];
$formatValues = static function (?string $value) use ($safeKeys): array { if ($value === null || trim($value) === '') return []; $decoded = json_decode($value, true); if (! is_array($decoded)) return [['label' => '', 'value' => $value]]; $items = []; foreach ($decoded as $key => $item) { if (! in_array((string) $key, $safeKeys, true) || is_array($item)) continue; $items[] = ['label' => ucwords(str_replace('_', ' ', (string) $key)), 'value' => $item === null || $item === '' ? '—' : (string) $item]; } return $items; };
$displayDate = static fn (?string $value): string => $value ? (new DateTimeImmutable($value))->format('d-m-Y') : '—';
?>
<main class="dashboard-container crm-page crm-history-page" aria-labelledby="crm-history-title">
    <span class="sr-only">Actor Date/time</span>
    <header class="crm-history-hero"><div class="crm-history-heading"><span class="crm-eyebrow">CRM / LEAD HISTORY</span><h1 id="crm-history-title"><?= esc($lead['full_name']) ?></h1><p><strong><?= esc($lead['lead_number']) ?></strong><span aria-hidden="true"> · </span><?= esc($lead['mobile_display'] ?? $lead['mobile_number']) ?><span aria-hidden="true"> · </span><?= esc($lead['email'] ?? 'No email') ?></p></div><div class="crm-history-actions"><a class="btn btn-dark" href="<?= base_url('admin/crm/leads/' . (int) $lead['id']) ?>">Back to Lead</a></div><dl class="crm-history-summary"><div><dt>Interested service</dt><dd><?= esc($lead['service_name'] ?? $lead['interested_service'] ?? 'Not specified') ?></dd></div><div><dt>Assigned user</dt><dd><?= esc($summary['assigned_user'] ?? 'Unassigned') ?></dd></div><div><dt>Current status</dt><dd><span class="<?= esc($statusClass((string) ($lead['status_code'] ?? 'default'))) ?>"><?= esc($lead['status_name'] ?? 'Unknown') ?></span></dd></div><div><dt>Priority</dt><dd><span class="crm-priority-badge crm-priority-<?= esc(strtolower((string) ($lead['priority'] ?? 'normal'))) ?>"><?= esc(ucfirst((string) ($lead['priority'] ?? 'Normal'))) ?></span></dd></div></dl></header>
    <section class="crm-summary-grid" aria-label="Activity summary"><article><span class="crm-summary-icon"><i class="bi bi-activity"></i></span><div><strong><?= (int) ($summary['total_events'] ?? 0) ?></strong><span>Total events</span></div></article><article><span class="crm-summary-icon"><i class="bi bi-clock-history"></i></span><div><strong><?= esc($summary['last_activity'] ? $displayDate($summary['last_activity']) : '—') ?></strong><span>Last activity</span></div></article><article><span class="crm-summary-icon"><i class="bi bi-calendar2-check"></i></span><div><strong><?= (int) ($summary['follow_ups'] ?? 0) ?></strong><span>Follow-ups</span></div></article><article><span class="crm-summary-icon"><i class="bi bi-chat-left-text"></i></span><div><strong><?= (int) ($summary['remarks_count'] ?? 0) ?></strong><span>Remarks</span></div></article><article><span class="crm-summary-icon"><i class="bi bi-arrow-left-right"></i></span><div><strong><?= esc($summary['conversion_status'] ?? 'Not converted') ?></strong><span>Conversion status</span></div></article></section>
    <section class="card crm-history-filter" aria-labelledby="history-filter-title"><div class="crm-card-head"><div><h2 id="history-filter-title">Find activity</h2><p>Filter activity within your permitted clinic scope.</p></div><?php if (array_filter($filters)): ?><a class="btn btn-light btn-sm" href="<?= base_url('admin/crm/leads/' . (int) $lead['id'] . '/history') ?>">Clear</a><?php endif; ?></div><form class="crm-history-filter-grid" method="get" action="<?= base_url('admin/crm/leads/' . (int) $lead['id'] . '/history') ?>"><div class="crm-history-search"><label for="historySearch">Search</label><input class="form-control" id="historySearch" name="actor" value="<?= esc($filters['actor']) ?>" placeholder="Search by actor"></div><div><label for="historyEventType">Event type</label><select class="form-control" id="historyEventType" name="event_type"><option value="">All events</option><?php foreach (($eventTypes ?? []) as $eventType): ?><option value="<?= esc($eventType) ?>" <?= $filters['event_type'] === $eventType ? 'selected' : '' ?>><?= esc($formatEvent($eventType)) ?></option><?php endforeach; ?></select></div><div><label for="historyFrom">From</label><input class="form-control" id="historyFrom" name="from" type="date" value="<?= esc($filters['from']) ?>"></div><div><label for="historyTo">To</label><input class="form-control" id="historyTo" name="to" type="date" value="<?= esc($filters['to']) ?>"></div><div class="crm-history-filter-actions"><button class="btn btn-dark" type="submit">Apply filters</button></div></form></section>
    <section class="crm-timeline-section" aria-labelledby="history-timeline-title"><div class="crm-section-heading"><div><span class="crm-eyebrow">ACTIVITY LOG</span><h2 id="history-timeline-title">History timeline</h2></div><span class="crm-record-count"><?= (int) ($total ?? count($history)) ?> event<?= ((int) ($total ?? count($history)) === 1 ? '' : 's') ?></span></div><?php if (empty($history)): ?><div class="crm-empty crm-history-empty"><i class="bi bi-clock-history" aria-hidden="true"></i><strong>No history found</strong><span>Lead updates, follow-ups, and conversions will appear here.</span><a class="btn btn-outline-dark btn-sm" href="<?= base_url('admin/crm/leads/' . (int) $lead['id']) ?>">Return to lead</a></div><?php else: ?><div class="crm-timeline"><?php $lastDay = null; foreach ($history as $entry): $event = (string) ($entry['event_type'] ?? ''); $day = substr((string) ($entry['created_at_display'] ?? ''), 0, 10); $previous = $formatValues($entry['previous_value'] ?? null); $new = $formatValues($entry['new_value'] ?? null); if ($day !== $lastDay): ?><div class="crm-timeline-day"><?= esc($day ?: 'Activity') ?></div><?php $lastDay = $day; endif; ?><article class="crm-timeline-item"><div class="crm-timeline-marker"><i class="bi <?= esc($icon($event)) ?>" aria-hidden="true"></i></div><div class="crm-timeline-card"><header><div><h3><?= esc($formatEvent($event)) ?></h3><span class="crm-category crm-category-<?= esc(strtolower($category($event))) ?>"><?= esc($category($event)) ?></span></div><time datetime="<?= esc((string) ($entry['created_at'] ?? '')) ?>"><?= esc($entry['created_at_display'] ?? '—') ?></time></header><div class="crm-timeline-meta"><span><i class="bi bi-person"></i><?= esc($entry['actor_name'] ?? 'System') ?></span><?php if (!empty($entry['follow_up_id'])): ?><a href="<?= base_url('admin/crm/follow-ups?lead_id=' . (int) $entry['lead_id']) ?>"><i class="bi bi-link-45deg"></i>Related follow-up</a><?php elseif (str_starts_with($event, 'converted_')): ?><a href="<?= base_url('admin/crm/leads/' . (int) $lead['id']) ?>"><i class="bi bi-link-45deg"></i>Conversion details</a><?php endif; ?></div><?php if ($previous || $new): ?><div class="crm-change-grid"><div><span>Previous value</span><div class="crm-change-box crm-change-old"><?php if ($previous): foreach ($previous as $item): ?><div><b><?= esc($item['label']) ?></b><span><?= esc($item['value']) ?></span></div><?php endforeach; else: ?><em>Nothing recorded</em><?php endif; ?></div></div><div class="crm-change-arrow" aria-hidden="true"><i class="bi bi-arrow-right"></i></div><div><span>New value</span><div class="crm-change-box crm-change-new"><?php if ($new): foreach ($new as $item): ?><div><b><?= esc($item['label']) ?></b><span><?= esc($item['value']) ?></span></div><?php endforeach; else: ?><em>Nothing recorded</em><?php endif; ?></div></div></div><?php endif; ?><?php if (!empty($entry['remarks'])): ?><div class="crm-timeline-remarks"><i class="bi bi-chat-left-text"></i><div><span>Remarks</span><p><?= nl2br(esc((string) $entry['remarks'])) ?></p></div></div><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?><div class="crm-pagination"><?= $pager->links('crm_history') ?></div></section>
</main>
<script>(function(){function format(value){var match=String(value||'').trim().match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);if(!match)return value;var hour=parseInt(match[1],10),suffix=hour>=12?'PM':'AM';hour=hour%12||12;return String(hour).padStart(2,'0')+':'+match[2]+' '+suffix;}document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.crm-change-box div').forEach(function(row){var label=row.querySelector('b'),value=row.querySelector('span');if(label&&value&&/follow up time/i.test(label.textContent)){value.textContent=format(value.textContent);}});});}());</script>
<?= $this->endSection() ?>
